		},
		{
			title = "Значение",
			text = [=[С тех пор как {link:malfurion-stormrage}Малфурион Ярость Бури{/link} затерялся в {link:emerald-dream}Изумрудном Сне{/link}, у друидов два средоточия и два предводителя. В {link:darnassus}Дарнассе{/link} с ветвей нового Древа Жизни правит верховный друид {link:fandral-staghelm}Фэндрал Олений Шлем{/link}. На Лунной поляне Ремулос хранит более старую землю. Эти двое больше не доверяют друг другу. Ремулос решил открыть поляну всем, кто служит живому миру, — {link:tauren}таурен{/link}у и ночному эльфу, {link:horde}Орде{/link} и {link:alliance}Альянсу{/link} равно. Именно с его поляны, а не из города верховного друида, {link:krueg-skullsplitter}Круг{/link} теперь призывает смертных защитников против опасностей {link:kalimdor}Калимдора{/link}.]=],
		},
		{
			title = "Сын полубога Кенария",
			text = [=[Хранители рощи — сыновья полубога Кенария, и Ремулос один из них. Его брат Зейтар был первым сыном. Давным-давно Зейтар нашел принцессу Терадрас, великую силу стихии земли, и она родила ему первых {link:centaurs}кентавр{/link}ов. Его собственные дети обратились против него и убили его, а Терадрас унесла его останки в пещеры {red:maraudon}Мародона{/red}. Ремулос считал, что его брат навсегда погублен гордыней и яростью. Потом, в {link:third-war}Третью войну{/link}, его отец пал от рук {link:orcs}орк{/link}ов в {link:ashenvale}Ясеневом лесу{/link}. Ремулос многое потерял из-за смертных народов. Поляну для них он не закрыл.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он охраняет Лунную поляну и друидов, которые п{link:ogres}огр{/link}ужены там в спячку.
• Он направляет {link:cenarion-circle}Круг Кенария{/link} из Святилища Ремулоса.
• Через своего мажордома {link:rabine-saturna}Рабин{/link}а Сатурну он призывает народы мира помочь {link:krueg-skullsplitter}Круг{/link}у в {link:silithus}Силитусе{/link} и в руинах города Эльдре'Талас.
• Он принимает на поляне {link:tauren}таурен{/link}ов, а через них и Орду.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О прошлом, которое было у хранителя до нынешнего века, написано мало: какую роль он сыграл в войнах древнего мира и когда впервые пришел хранить Лунную поляну. Эта запись говорит лишь о том, что открывают его слова и его пост.]=],
		},
	},
	chapters = {
		{
			title = "Разделенный Круг",
			hint = "Откликнитесь на зов Круга на Лунной поляне.",
			text = [=[Когда {link:krueg-skullsplitter}Круг{/link} попросил помощи на дальнем западе, зов разошелся через {link:thunder-bluff}Громовой Утес{/link} и через {link:darnassus}Дарнасс{/link}. В Громовом Утесе его услышали с радостью. В Дарнассе верховный друид отказался выслушать его сам. Он предостерег, что {link:moonglade}Лунная поляна{/link} говорит одну лишь пропаганду и что только он вывел свой народ из тьмы. Его собственный помощник признал, что верховный друид и хранитель подозревают друг друга в обмане. Тем, кто все же пришел на поляну, обещали, что они среди друзей и что никакое зло из Дарнасса их там не достанет.]=],
		},
		{
			title = "Семя хранителя Зейтара",
			hint = "Принесите хранителю дар от духа его брата.",
			text = [=[Глубоко в Мародоне, где Терадрас держала его останки, задержался дух, который оставил Зейтар. Он не желал покидать своих детей даже после всего, что они сделали. Вместо этого он послал первое семя, выросшее из жизни, которую питали его останки, и весть для брата: его дух пребывает там. Когда семя достигло Лунной поляны, Ремулос понял. Его брат не был потерян. Он вернул себя природе, как велел его долг, и наконец обрел покой. Хранитель почувствовал, что однажды это семя будет много значить для народа той истерзанной войной земли.]=],
		},
	},
	mentions = {
