		{ id = "malfurion-stormrage", name = "Малфурион Ярость Бури", note = "первый друид, который спит" },
		{ id = "fandral-staghelm", name = "Фэндрал Олений Шлем", note = "его соперник в Дарнассе" },
		{ id = "rabine-saturna", name = "Рабин Сатурна", note = "его мажордом" },
		{ id = "tajarri", name = "Таджарри", note = "страж его святилища" },
		{ id = "keeper-marandis", name = "хранитель Марандис", note = "ищет останки его брата" },
		{ id = "hamuul-runetotem", name = "Хамуул Рунический Тотем", note = "приводит тауренов в Круг" },
	},
})

Translate("ruRU", "rabine-saturna", {
	title = "Рабин Сатурна",
	subtitle = "Мажордом хранителя Ремулоса",
	found = "Ночная Гавань, у озера",
	hint = "Ищите мажордома хранителя в деревне Ночная Гавань.",
	allegiance = "Круг Кенария",
	aliases = { "Рабин" },
	sections = {
		{
			title = "Обзор",
			text = [=[Рабин Сатурна — мажордом хранителя {link:keeper-remulos}Ремулос{/link}а. Он говорит от имени хранителя с теми, кто приходит на Лунную поляну, и приветствует их от имени всех, кто живет на священной поляне. Он терпелив и учтив и никогда не забывает долга. Архивариус {link:umber}Умбер{/link} называет его наседкой Ночной Гавани, и не всегда по-доброму.]=],
		},
		{
			title = "Значение",
			text = [=[Рабин — рука, которую {link:moonglade}Лунная поляна{/link} протягивает миру. Через него {link:krueg-skullsplitter}Круг{/link} просит чужаков из любого народа сделать то, чего его друиды не могут сделать одни. Он верит, что сбережение {link:azeroth}Азерота{/link} — общее дело {link:horde}Орды{/link} и {link:alliance}Альянса{/link}, каковы бы ни были их распри и что бы ни говорил верховный друид {link:darnassus}Дарнасса{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он принимает на поляне посланцев Громового Утеса и {link:darnassus}Дарнасс{/link}а и обещает им там защиту.
• Он посылает своих людей на запад, в {link:silithus}Силитус{/link}, где некогда шла древняя война между ночными эльфами и чуждой силой.
• Он посылает искателей в руины Деревни Южного Ветра за Реликварием Чистоты.
• Он стремится запечатать осколок Сквернолоза из города Эльдре'Талас.]=],
		},
	},
	chapters = {
		{
			title = "Пустошь",
			hint = "Отнесите письмо мажордома в пустоши за Ун'Горо.",
			text = [=[К западу от {link:un-goro-crater}Кратера Ун'Горо{/link} лежит пустыня, которую помнят немногие ночные эльфы. Давным-давно их народ сражался там со страшным врагом и запечатал его. Рабин опасается, что теперь нечто трудится над тем, чтобы его пробудить. Он отправил письмо посланцу {link:krueg-skullsplitter}Круг{/link}а {link:layo-starstrike}Лайо{/link} Звездному Удару на {link:valor-s-rest}Погост Отважных{/link} — место п{link:ogres}огр{/link}ебения павших в пустошах. То, что Лайо там нашел, начало подтверждать его правоту. Со временем Лайо прислал домой странный предмет, запечатанный в хитине и предназначенный для архивариуса Ночной Гавани.]=],
		},
		{
			title = "Сквернолоз",
			hint = [=[Принесите мажордому надежно запечатанный осколок оскверненной лозы.]=],
			text = [=[В восточных залах города Эльдре'Талас, в {link:feralas}Фераласе{/link}, {link:satyrs}сатир{/link} Алззин Перевертень захватил Плод Плодородия и осквернил его, превратив в Сквернолоз. Ни один обычный сосуд не мог вместить столь мерзкую вещь. Рабин вспомнил о Реликварии Чистоты, который много лет назад был оставлен в Деревне Южного Ветра, в {link:silithus}Силитус{/link}е. Когда реликварий вернули и осколок запечатали в нем, он назвал того, кто его принес, героем {link:krueg-skullsplitter}Круг{/link}а. Война, предупредил он, далеко не окончена.]=],
		},
	},
	mentions = {
		{ text = "Рабин Сатурна" },
		{ text = "Рабин Сатурна" },
		{ text = "Пустошь" },
		{ text = "Раскрытие тайн прошлого" },
		{ text = "Реликварий Чистоты" },
		{ text = "Осколки Сквернолоза" },
	},
	bonds = {
		{ id = "keeper-remulos", name = "хранитель Ремулос", note = "его господин" },
		{ id = "umber", name = "Умбер", note = "архивариус Круга" },
		{ id = "hamuul-runetotem", name = "Хамуул Рунический Тотем", note = "присылает к нему тауренов" },
		{ id = "mathrengyl-bearwalker", name = "Матренгил Медвежья Поступь", note = "присылает к нему ночных эльфов" },
	},
})

Translate("ruRU", "dendrite-starblaze", {
	title = "Дендрит Звездное Пламя",
	subtitle = "Наставник молодых друидов",
	found = "Ночная Гавань, на севере деревни",
	hint = [=[Ищите друида Ночной Гавани, который учит молодых их первым обликам.]=],
	allegiance = "Круг Кенария",
	aliases = { "Дендрит" },
	sections = {
		{
			title = "Обзор",
			text = [=[Дендрит Звездное Пламя — друид {link:krueg-skullsplitter}Круг{/link}а Кенария, который учит в Ночной Гавани. Почти каждый молодой друид ночных эльфов и {link:tauren}таурен{/link}ов проходит через его руки. Каждого он встречает тихой молитвой, обращенной к отцу Кенарию, и малым, незримым жестом, который наполняет ученика силой. Потом он отправляет их учиться у самой дикой природы.]=],
		},
		{
			title = "Значение",
			text = [=[Дендрит хранит древнейшую традицию друидов: облики природы нужно заслужить, а не просто получить. Он посылает учеников к великим духам, в озеро и к больным зверям мира и судит о них по тому, что они принесут обратно. Теперь к нему приходят и друиды народа {link:skyborne}шен'дорай{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он посылает молодых друидов к Великому духу медведя, чтобы они познали природу медведя.
• Он назначает Испытание озера и Испытание морского льва тем, кто хочет принять водный облик.
• Он послал молодых друидов на {link:darkshore}Темные берега{/link}, когда {link:auberdine}Аубердин{/link} попросил у Лунной поляны помощи с отравленными оленями.
• Он посылает учеников к Великому духу кошки, а друидов {link:skyborne}шен'дорай{/link} — к духу их собственной родины.]=],
		},
	},
	chapters = {
		{
			title = "Путь Когтя",
			hint = "Найдите Великого духа медведя по слову наставника.",
			text = [=[Первый урок, который дает Дендрит, — всегда медведь. Он посылает каждого ученика к Великому духу медведя на северо-западе поляны и ждет. Когда они возвращаются, он ищет перемену в их глазах: новую мудрость и силу, пока еще не собранную воедино.]=],
		},
		{
			title = "Яд в воде",
			hint = "Помогите оленям Темных берегов от имени Круга.",
			text = [=[{link:auberdine}Аубердин{/link} попросил у Лунной поляны помощи, и Дендрит сделал из этого урок. Это не упражнение, предупредил он. Вода Водопада Скалистого отравляла оленей {link:darkshore}Темных берегов{/link}, и ученику нужно было исцелить их своими руками, как сделал бы несведущий, прежде чем научиться делать это одним словом. Аубердин прислал свою благодарность. Дендрит добавил и собственное предостережение: кое-кто в {link:darnassus}Дарнасс{/link}е предпочитает не видеть порчи, что расползается по земле.]=],
		},
		{
			title = "Великая кошка",
			hint = "Заслужите благословение Великого духа кошки.",
			text = [=[В эти дни Дендрит посылает своих учеников и на юг, к Великому духу кошки возле Келий {link:malfurion-stormrage}Малфурион{/link}а. Для друидов {link:skyborne}шен'дорай{/link} у него есть другой проводник: рожденный ветром дух кошки с их собственного острова, который пришел на поляну и попросил прислать их, назвав по имени.]=],
		},
	},
	mentions = {
		{ text = "{link:moonglade}Лунная поляна{/link}" },
		{ text = "{link:moonglade}Лунная поляна{/link}" },
		{ text = "{link:great-bear-spirit}Великий дух медведя{/link}" },
		{ text = "Урок, который предстоит усвоить" },
		{ text = "Испытание морского льва" },
		{ text = "Новые уроки" },
		{ text = "Власть над ядом" },
		{ text = "{link:great-cat-spirit}Великий дух кошки{/link}" },
		{
			text = [=[{link:great-cat-spirit}Великий дух кошки{/link}, рожденный ветром]=],
		},
	},
	bonds = {
		{ id = "great-bear-spirit", name = "Великий дух медведя", note = "первый учитель его учеников" },
		{ id = "great-cat-spirit", name = "Великий дух кошки", note = "испытывает его учеников" },
		{ id = "avatar-of-saeyleenan", name = "Аватара Сэйлинана", note = "учит его учеников из народа шен'дорай" },
		{ id = "tajarri", name = "Таджарри", note = "судит Испытание озера" },
		{ id = "alanndarian-nightsong", name = "Аланндариан Ночная Песнь", note = "попросил помощи у Лунной поляны" },
		{ id = "mathrengyl-bearwalker", name = "Матренгил Медвежья Поступь", note = "присылает ему учеников" },
	},
})

Translate("ruRU", "umber", {
	title = "Умбер",
	subtitle = "Архивариус Круга Кенария",
	found = "Среди книжных полок Ночной Гавани",
	hint = "Ищите архивариуса, который бродит среди полок Ночной Гавани.",
	allegiance = "Круг Кенария",
	sections = {
		{
			title = "Обзор",
			text = [=[Умбер — архивариус {link:krueg-skullsplitter}Круг{/link}а Кенария. Он блестящ, забывчив и слегка не в себе, и он спасал тома в таком плачевном виде, что большинство ученых не решились бы их и открыть. Он бормочет себе под нос, пока ищет на полках бумаги, которые куда-то задевал. Он слышал приглушенные разговоры об ужасах пустыни. Он не любит никаких насекомых и рад оставаться при своих книгах.]=],
		},
		{
			title = "Значение",
			text = [=[Умбер открыл первое окно в прошлое {link:silithus}Силитуса{/link}. В куске хитина, присланном из пустыни, оказался дневник, написанный на очень старой форме языка ночных эльфов.]=],
		},
	},
	mentions = {
		{ text = "Умбер, архивариус" },
		{ text = "Раскрытие тайн прошлого" },
		{ text = "Под хитином оказалось..." },
	},
	bonds = {
		{ id = "rabine-saturna", name = "Рабин Сатурна", note = "наседка, по его словам" },
	},
})

Translate("ruRU", "loganaar", {
	title = "Логанаар",
	subtitle = "Наставник друидов Ночной Гавани",
	found = "Ночная Гавань",
	hint = [=[Ищите друида, который обучает в Ночной Гавани друидов самого Круга.]=],
	allegiance = "Круг Кенария",
	sections = {
		{
			title = "Обзор",
			text = [=[Логанаар учит искусствам друида в Ночной Гавани. В отличие от наставников {link:darnassus}Дарнасс{/link}а и Громового Утеса, он не служит ни одному городу. Он обучает любого друида {link:krueg-skullsplitter}Круг{/link}а, который приходит на поляну, будь то {link:night-elves}ночной эльф{/link} или {link:tauren}таурен{/link}, и ему нет дела ни до их городов, ни до их распрей. В Круге, разделенном между Лунной поляной и Дарнассом, его уроки принадлежат одной только поляне.]=],
		},
		{
			title = "Значение",
			text = [=[Часто именно Логанаар первым узнаёт, что кто-то вдалеке просит помощи друида. Когда охотник {link:torwa-pathfinder}Торва Следопыт{/link} прислал из {link:un-goro-crater}Кратера Ун'Горо{/link} весть, что помочь ему может только друид, передал ее дальше именно Логанаар.]=],
		},
	},
	mentions = {
		{ text = "{link:torwa-pathfinder}Торва Следопыт{/link}" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Дендрит Звездное Пламя", note = "учит в той же деревне" },
	},
})

Translate("ruRU", "tajarri", {
	title = "Таджарри",
	subtitle = "Страж Святилища Ремулоса",
	found = "Святилище Ремулоса",
	hint = "Поговорите со стражем, которая бережет святилище хранителя.",
