			text = [=[Таджарри — одна из самых доверенных стражей Лунной поляны. Она бережет {link:shrine-of-remulos}Святилище Ремулоса{/link} и считает это честью. Она присматривает за молодыми друидами, которые бегут от озера с тускнеющими безделушками в руках, и торопит их, когда времени остается мало. Те же воды могут обыскивать и другие друиды, а безделушка не ждет. Знает она и о втором испытании и тех, кто ищет половины Подвески морского льва, отправляет расспросить жителей поляны, где они лежат.]=],
		},
		{
			title = "Значение",
			text = [=[Таджарри — судья Испытания озера. Через нее каждый молодой друид узнаёт, что святилище чтит древнейший долг {link:krueg-skullsplitter}Круг{/link}а — сбережение равновесия природы.]=],
		},
	},
	mentions = {
		{ text = "Испытание озера" },
		{ text = "Испытание озера" },
		{ text = "Испытание морского льва" },
	},
	bonds = {
		{ id = "keeper-remulos", name = "хранитель Ремулос", note = "хозяин ее святилища" },
		{ id = "dendrite-starblaze", name = "Дендрит Звездное Пламя", note = "присылает к ней молодых" },
	},
})

Translate("ruRU", "great-bear-spirit", {
